// components/navigation/overlay-layers.ts — Unified Overlay Stacking Hierarchy
// Establishes a predictable, collision-free z-index hierarchy across the entire XEURIE architecture.
// Strict stacking ensures modals, slide-overs, dropdowns, and toasts never collide or occlude incorrectly.

export const OVERLAY_LAYERS = {
  /** Sticky header chrome and navigation bars */
  HEADER: "z-30",

  /** Account menus, route dropdowns, and flyout popovers */
  DROPDOWN: "z-40",

  /** Full-viewport mobile navigation drawers (backdrop & sheet) */
  MOBILE_DRAWER: "z-50",

  /** Standard dialogs, checkout flow, restock alert, legal terms */
  MODAL: "z-[60]",

  /** Critical security confirmation modals (pre-payment, emergency) */
  CRITICAL_MODAL: "z-[80]",

  /** Customer Vault slide-over drawer (preserved contract: z-[100] backdrop, z-[101] sheet) */
  VAULT_BACKDROP: "z-[100]",
  VAULT_DRAWER: "z-[101]",

  /** Portaled select dropdowns, contextual popovers (rendered above modals & drawers) */
  POPOVER: "z-[105]",

  /** Global feedback toasts & realtime telemetry notices (always topmost) */
  TOAST: "z-[110]",
} as const;

export type OverlayLayerKey = keyof typeof OVERLAY_LAYERS;
